"""Function exceeding LOC threshold (>= 50 lines)."""


def build_report(data):
    report = {}
    report["title"] = data.get("title", "Untitled")
    report["date"] = data.get("date", "unknown")
    report["author"] = data.get("author", "anonymous")
    report["version"] = data.get("version", "1.0")
    report["department"] = data.get("department", "general")
    report["category"] = data.get("category", "misc")
    report["priority"] = data.get("priority", "normal")
    report["status"] = data.get("status", "draft")
    report["reviewer"] = data.get("reviewer", "none")
    report["approver"] = data.get("approver", "none")
    report["tags"] = data.get("tags", [])
    report["references"] = data.get("references", [])
    report["summary"] = data.get("summary", "")
    report["introduction"] = data.get("introduction", "")
    report["methodology"] = data.get("methodology", "")
    report["results"] = data.get("results", "")
    report["discussion"] = data.get("discussion", "")
    report["conclusion"] = data.get("conclusion", "")
    report["appendix_a"] = data.get("appendix_a", "")
    report["appendix_b"] = data.get("appendix_b", "")
    report["appendix_c"] = data.get("appendix_c", "")
    report["footnotes"] = data.get("footnotes", [])
    report["figures"] = data.get("figures", [])
    report["tables"] = data.get("tables", [])
    report["charts"] = data.get("charts", [])
    report["glossary"] = data.get("glossary", {})
    report["index"] = data.get("index", [])
    report["bibliography"] = data.get("bibliography", [])
    report["acknowledgements"] = data.get("acknowledgements", "")
    report["abstract"] = data.get("abstract", "")
    report["keywords"] = data.get("keywords", [])
    report["doi"] = data.get("doi", "")
    report["isbn"] = data.get("isbn", "")
    report["issn"] = data.get("issn", "")
    report["publisher"] = data.get("publisher", "")
    report["edition"] = data.get("edition", "1st")
    report["language"] = data.get("language", "en")
    report["pages"] = data.get("pages", 0)
    report["word_count"] = data.get("word_count", 0)
    report["char_count"] = data.get("char_count", 0)
    report["paragraph_count"] = data.get("paragraph_count", 0)
    report["section_count"] = data.get("section_count", 0)
    report["image_count"] = data.get("image_count", 0)
    report["table_count"] = data.get("table_count", 0)
    report["chart_count"] = data.get("chart_count", 0)
    report["font_family"] = data.get("font_family", "Arial")
    report["font_size"] = data.get("font_size", 12)
    report["line_spacing"] = data.get("line_spacing", 1.5)
    report["margin_top"] = data.get("margin_top", 1.0)
    return report
